INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q280345', 'Battle of Mobei', 'The Battle of Mobei (simplified Chinese: 漠北之战; traditional Chinese: 漠北之戰; pinyin: Mòběi zhī Zhàn) was a military campaign fought mainly in modern-day Mongolia, in the extreme cold and barren lands of the Gobi Desert. It was part of a major strategic offensive launched by the Han dynasty in the winter of January 119 BC, into the heartland of the nomadic Xiongnu.', -119, 1, NULL, -119, 6, NULL, 'month', 'January 119 BCE – June 119 BCE', 45, 'https://en.wikipedia.org/wiki/Battle_of_Mobei'),
  ('Q9172907', 'Battle of Dalan Baljut', 'The Battle of Dalan Baljut was fought in 1187 between Temüjin (later known as Genghis Khan) and Jamukha, his blood brother. Although Temüjin and Jamukha were close friends for many years, they began to drift apart as time went on.', 1187, NULL, NULL, NULL, NULL, NULL, 'year', '1187', 45, 'https://en.wikipedia.org/wiki/Battle_of_Dalan_Baljut'),
  ('Q3874305', 'Battle of Jao Modo', 'The Battle of Jao Modo (Mongolian: Зуунмод-Тэрэлжийн тулалдаан; Chinese: 昭莫多之戰; pinyin: zhāo mò duō zhī zhàn) also known as the Battle of Zuunmod (literally "Battle of the Hundred Trees"), was fought on June 12, 1696, on the banks of the upper Terelj river 60 kilometres (37 mi) east of the modern-day Mongolian capital Ulaanbaatar. A Dzungar-Mongol army under the command of Galdan Boshugtu Khan was defeated by Qing armies personally led by the Kangxi Emperor.', 1696, NULL, NULL, NULL, NULL, NULL, 'year', '1696', 37, 'https://en.wikipedia.org/wiki/Battle_of_Jao_Modo'),
  ('Q152533', 'Treaty of friendship and alliance between the Government of Mongolia and Tibet', 'A Treaty of friendship and alliance between the Government of Mongolia and Tibet was signed on 11 January 1913 (corresponding to 29 December 1912 of the Julian calendar), at Urga (now Ulaanbaatar). This treaty''s text in Mongolian was published by the Mongolian Academy of Sciences in 1982, and in 2007 an original copy in Tibetan language and script surfaced from Mongolian archives.', 1913, 1, 11, NULL, NULL, NULL, 'day', '11 January 1913', 67, 'https://en.wikipedia.org/wiki/Treaty_of_friendship_and_alliance_between_the_Government_of_Mongolia_and_Tibet'),
  ('Q4527029', 'Battle of Urga', 'The Battle of Urga was a battle in the Russian civil war. During 1 to 4 February 1921, White Russian soldiers under Baron Roman von Ungern-Sternberg defeated the numerically superior Chinese garrison and subsequently liberated Mongolia from Chinese occupation.', 1921, 2, 1, 1921, 2, 4, 'day', '1 February 1921 – 4 February 1921', 39, 'https://en.wikipedia.org/wiki/Battle_of_Urga'),
  ('Q890631', 'Battle of Khalkhyn Temple', 'The Battle of Khalkhyn Temple (Mongolian: Халхын сүмийн мөргөлдөөн Khalkhyn sümiin mörgöldöön; Chinese: Halhamiao Incident, 哈爾哈廟事件; Japanese ハルハ廟事件 Haruhabyō-jiken) of 1935 was one of the border conflicts between the Soviet Union, Mongolia, Japan and Manchukuo which occurred from 1932 to 1939. The incident took place on the border of Manchukuo and Mongolia near the Buddhist temple of Khalkhyn (Temple of Khalkha), located northeast of Buir Lake in present-day Inner Mongolia, China.', 1935, 1, 8, NULL, NULL, NULL, 'day', '8 January 1935', 34, 'https://en.wikipedia.org/wiki/Battle_of_Khalkhyn_Temple'),
  ('Q188925', 'Battles of Khalkhin Gol', 'The Battles of Khalkhin Gol (Russian: Бои на Халхин-Голе, romanized: Boy na Khalkhin-Gole; Mongolian: Халхын голын байлдаан, romanized: Khalkhyn golyn baildaan), known in Japan as the Nomonhan Incident (Japanese: ノモンハン事件, Hepburn: Nomonhan jiken) after Nomonhan Burd Obo, were the decisive engagements of the undeclared Soviet–Japanese border conflicts which involved the Soviet Union, Mongolia, Japan, and Manchukuo in 1939. The conflict is named after the river Khalkhin Gol, which passes through the battlefield.', 1939, 5, 11, 1939, 9, 16, 'day', '11 May 1939 – 16 September 1939', 74, 'https://en.wikipedia.org/wiki/Battles_of_Khalkhin_Gol'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q134698175', '2025 Mongolian protests', 'On 14 May 2025, anti-government demonstrations began in Ulaanbaatar, the capital of Mongolia, following reports of extravagant spending by the son of Prime Minister Luvsannamsrain Oyun-Erdene. The protests, primarily led by young Mongolians, centered on broader concerns about government corruption, inequality, and the influence of political elites and their families.', 2025, 5, 14, 2025, 6, 3, 'day', '14 May 2025 – 3 June 2025', 45, 'https://en.wikipedia.org/wiki/2025_Mongolian_protests');

